// DSH 悬浮窗 · 把 DeepSeek Harness 手机页面置顶成悬浮窗
// https://github.com/xiangshu2026/dsh-float

package com.alpha.dshfloat;

/** 手机端精简样式：单栏 / 大字 / 藏思考 / 藏桌宠 / 藏联网球 / 会话抽屉 / 主列撑满。 */
public final class TidyCss {

    public static final String CSS =
"/* ============================================\n   DSH 手机精简版 · DSH Float 手机精简版\n   单栏 / 大字 / 无思考过程 / 输入框贴底\n   ============================================ */\n\n/* 2. 顶栏矮而清爽 */\n.Dc7zOa_header {\n  height: 34px !important; min-height: 34px !important;\n  padding: 0 8px !important;\n  background: #14161A !important;\n  border-bottom: 1px solid #ffffff12 !important;\n}\n\n/* 3. 容器撑满 */\n.BynINW_frame { height: 100vh !important; }\n.Dc7zOa_root { flex: 1 1 auto !important; height: 100% !important; min-height: 0 !important; }\n.Dc7zOa_body { flex: 1 1 auto !important; min-height: 0 !important; }\n.Dc7zOa_scrollBody {\n  flex: 1 1 auto !important; min-height: 0 !important;\n  padding: 0 12px !important;\n  justify-content: flex-start !important;\n}\n\n/* 4. 字体放大 */\n#root { font-size: 17px !important; line-height: 1.75 !important; -webkit-text-size-adjust: 100% !important; }\n.Dc7zOa_scrollBody p, .Dc7zOa_scrollBody li,\n.Dc7zOa_scrollBody div, .Dc7zOa_scrollBody span {\n  font-size: 17px !important; line-height: 1.75 !important;\n}\n.Dc7zOa_scrollBody pre, .Dc7zOa_scrollBody code { font-size: 14px !important; line-height: 1.6 !important; }\n.RlGAzG_input textarea, .RlGAzG_input, .Dc7zOa_composerSeat textarea {\n  font-size: 17px !important; line-height: 1.6 !important;\n}\n.Dc7zOa_header * { font-size: 15px !important; }\n\n/* 5. 隐藏思考过程与工具调用折叠块 */\n.WW4l1q_root { display: none !important; }\n\n/* 6. 隐藏底部 token 统计条（DeepSeek App 没有这个） */\n.RlGAzG_dock, .iq1doa_root { display: none !important; }\n\n/* 7. 输入框贴底紧凑 */\n.Dc7zOa_composerSeat {\n  position: static !important; flex: 0 0 auto !important;\n  height: auto !important; min-height: 0 !important;\n  margin-top: auto !important;\n  padding: 4px 8px 10px !important;\n  background: #14161A !important;\n}\n.Dc7zOa_composerStack { max-width: 100% !important; margin: 0 !important; padding: 0 !important; }\n.RlGAzG_root { max-width: 100% !important; margin: 0 !important; }\n.RlGAzG_hero { margin: 0 !important; padding: 0 !important; }\n.RlGAzG_card { border-radius: 18px !important; }\n.Dc7zOa_composerSeat > .Hqq-bq_root { display: none !important; }\n\n/* 8. 滚动条细化 */\n::-webkit-scrollbar { width: 3px !important; height: 3px !important; }\n::-webkit-scrollbar-thumb { background: #ffffff22 !important; border-radius: 3px !important; }\n::-webkit-scrollbar-track { background: transparent !important; }\n/* ===== 手机极简：只留对话（需求）===== */\n.Dc7zOa_tabs { display: none !important; }\n.EBLgjq_trigger,\n.WgQWqa_main,\n._4Nnt6q_moreButton,\n.dzXS4q_button { display: none !important; }\n.Dc7zOa_header { height: 30px !important; min-height: 30px !important; padding: 0 6px !important; }\n/* ===== 隐藏桌宠（小鲸鱼挂件 / whale bubble）===== */\n[class^=\"dshwv-\"], [class*=\" dshwv-\"] { display: none !important; }\n#dsh-whale-pet, .dsh-whale-pet { display: none !important; }\n/* ========== 隐藏 DSH 自带的悬浮件（联网小球 / 调试面板 / 光标）========== */\n#dsh-ego-fab,\n#dsh-ego-panel,\n.dsh-ego-live,\n.ego-agent-cursor-overlay { display: none !important; }\n\n/* ========== 布局修复：主列撑满（根因：frame 是 CSS Grid，藏侧栏后列宽不重算） ========== */\n.BynINW_frame { grid-template-columns: 1fr 0px 0px !important; }\n\n/* ========== 会话列表：默认隐藏，点 ☰ 弹出抽屉 ========== */\n.BynINW_sidebarCol { display: none !important; }\n\nbody.alpha-sidebar-open .BynINW_sidebarCol {\n  display: block !important;\n  position: fixed !important;\n  left: 0 !important; top: 0 !important; bottom: 0 !important;\n  width: 80vw !important;\n  max-width: 330px !important;\n  height: 100vh !important;\n  z-index: 99999 !important;\n  background: #14161A !important;\n  box-shadow: 6px 0 26px #000b !important;\n  overflow: hidden !important;\n}\nbody.alpha-sidebar-open .BynINW_centerCol {\n  filter: brightness(.55) !important;\n  pointer-events: none !important;\n}\n/* 抽屉里的会话列表允许滚动 */\nbody.alpha-sidebar-open .BynINW_sidebarCol * { overflow: visible; }";

    private TidyCss() {}
}
